  function buildEntry(input, proceso) {
    const etq = (input.etiquetas || []).filter(e => e && e.trim());
    const item = {
      Linea: input.linea || '',
      MetalBase: input.metal || '',
      Proceso: proceso || ''
    };
    for (let i = 1; i <= MAX_ETIQUETAS; i++) item['Etiqueta' + i] = etq[i - 1] || '';
    return item;
  }

