      if (!inSet(f.metals, pn.metal)) return false;
      if (!inSet(f.procesos, pn.proceso)) return false;
      if (!inSet(f.lineas, pn.linea)) return false;
      if (!inSet(f.departamentos, pn.departamento)) return false;
